from jsonb_to_recordset($json$[{"id":"che-pe-269","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Inner electrons shield valence electrons from the full attraction of the","options":["neighbouring atoms","nucleus","neutron cloud","crystal field"],"answer_index":1,"explanation":"Screening (shielding) is the reason Zeff is smaller than Z.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-270","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Effective nuclear charge felt by the outermost electron","options":["falls across a period","increases across a period","is zero for all metals","equals the mass number"],"answer_index":1,"explanation":"Electrons are added to the same shell, which screens poorly, so Zeff climbs left to right.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-271","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Down a group, the increase in shielding and the addition of shells outweigh the rise in nuclear charge, so","options":["atomic size shrinks","atomic size grows","IE rises sharply","all elements become noble gases"],"answer_index":1,"explanation":"The net result is a larger, more loosely held valence electron in the heavier congener.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-272","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"In a given period, a smaller atomic size is generally accompanied by a","options":["smaller ionisation enthalpy","larger ionisation enthalpy","negative nuclear charge","new f subshell"],"answer_index":1,"explanation":"The outer electron is closer to the nucleus and harder to remove in the smaller atom.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-273","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Non-metallic character increases from left to right across a","options":["group","period","set of alkali metals","lanthanoid contraction pair"],"answer_index":1,"explanation":"IE and electronegativity rise, so the tendency to gain or share electrons grows.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-274","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Melting points, boiling points and densities of elements also display","options":["no variation with Z","periodic variation","a linear fall with mass number only","identical values in every group"],"answer_index":1,"explanation":"These bulk properties repeat in a rough pattern because bonding type and size are themselves periodic.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-275","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"s-block elements are strongly electropositive metals, except for","options":["sodium and potassium","hydrogen and helium","calcium and barium","all of group 2"],"answer_index":1,"explanation":"H and He are non-metals placed in period 1; the rest of the s-block are typical metals.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-276","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"The p-block is the only block that contains metals, metalloids and non-metals in the","options":["s-block groups","same set of groups","f-block rows","first period alone"],"answer_index":1,"explanation":"Group 14, for example, runs from non-metal C through metalloid Si/Ge to metals Sn and Pb.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-277","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Screening of the nuclear charge is poorer by d and f electrons than by","options":["the nucleus itself","s and p electrons of the same shell","neutrons","alpha particles"],"answer_index":1,"explanation":"Penetrating s (and p) electrons cancel Z more effectively; d and f electrons leave a higher Zeff on the outside.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"easy","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-278","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Neon has both a very small covalent radius and the highest first ionisation enthalpy of","options":["period 3","period 2","the alkali metals","the lanthanoids"],"answer_index":1,"explanation":"Closed-shell compactness and maximum Zeff in that row make Ne the extreme of both trends.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-279","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"From lithium to caesium, ionisation enthalpy falls while atomic radius rises, so the two trends reinforce the","options":["decrease in metallic character","increase in metallic character","rise of electronegativity","formation of noble gases"],"answer_index":1,"explanation":"A larger, more loosely held ns¹ electron makes the heavier alkali metal more metallic.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false},{"id":"che-pe-280","chapter_id":"chemistry-classification-of-elements-and-periodicity-in-properties","subject_id":"chemistry","stem":"Fluorine is more electronegative than chlorine, yet chlorine has the more negative electron gain enthalpy — a pair of trends that","options":["always run in step","do not run in step","apply only to metals","forbid any F–Cl bond"],"answer_index":1,"explanation":"χ follows size/Zeff, while ΔegH of F is reduced by 2p–2p repulsion; the two properties therefore order F and Cl differently.","images":[],"source":{"name":"ASTRA chemistry practice set","license":"Original syllabus-based practice questions (exam-frequent themes; not verbatim past papers)"},"difficulty":"medium","concept_id":"periodic-trends-general","appear_count":0,"years":[],"exams":[],"verified":false}]$json$::jsonb) as x(
